(() => {
  'use strict';
  const isHelper = el => {
    if (!el || el.nodeType !== 1) return false;
    const text = (el.innerText || el.textContent || '').replace(/\s+/g,' ').trim();
    const cls = String(el.className || '');
    const id = String(el.id || '');
    const marker = `${id} ${cls}`.toLowerCase();
    return (/llfetcher/.test(marker) || /helper|debug/.test(marker)) &&
      (/LLFetcher\s*[·•-]\s*(Helper Panel|Yardımcı Panel)/i.test(text) ||
       /Ders algılama ve bağlantı durumu/i.test(text));
  };
  function hide() {
    const nodes = document.querySelectorAll('body *');
    for (const el of nodes) {
      if (isHelper(el)) {
        // Hide the smallest matching container to avoid hiding the whole page.
        let target = el;
        for (let i=0; i<3 && target.parentElement && target.parentElement !== document.body; i++) {
          const p = target.parentElement;
          const pText = (p.innerText || '').replace(/\s+/g,' ').trim();
          if (pText.length > 800) break;
          target = p;
        }
        target.style.setProperty('display','none','important');
        target.setAttribute('aria-hidden','true');
      }
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded',hide,{once:true}); else hide();
  const mo = new MutationObserver(() => hide());
  mo.observe(document.documentElement,{childList:true,subtree:true});
})();


/* 3.1.1: Explicitly hide the injected content-script root as requested. */
(() => {
  const hideRoot = () => {
    const root = document.getElementById('content-script-root');
    if (root && !root.hasAttribute('hidden')) root.setAttribute('hidden', '');
  };
  hideRoot();
  const observer = new MutationObserver(() => hideRoot());
  observer.observe(document.documentElement, { childList: true, subtree: true });
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', hideRoot, { once: true });
  }
})();
